window.futvizVista("xg-vs-goles-90","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"xg-vs-goles-90\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"xg-vs-goles-90\"]={\"id\":\"xg-vs-goles-90\",\"titulo\":\"xG vs. goles por 90'\",\"bajada\":\"Sobre la diagonal marc\u00f3 m\u00e1s que su xG; a la derecha de la l\u00ednea, el 30% con m\u00e1s xG.\",\"pregunta\":\"\u00bfQui\u00e9n genera m\u00e1s ocasiones y qui\u00e9n las convierte?\",\"tabla\":\"jugadores\",\"entidad\":\"jugadores\",\"x\":{\"col\":\"npxg90\",\"label\":\"xG sin penales por 90'\",\"corto\":\"xG por 90'\",\"dec\":2},\"y\":{\"col\":\"npg90\",\"label\":\"Goles sin penales por 90'\",\"corto\":\"Goles por 90'\",\"dec\":2},\"referencia\":{\"tipo\":\"diagonal\",\"dif\":\"goles \u2212 xG sin penales por 90'\",\"sobre\":\"Marcan m\u00e1s de lo esperado\",\"bajo\":\"Marcan menos de lo esperado\",\"decDif\":2,\"zonas\":{\"pct\":0.7,\"tr\":\"Muchas ocasiones y las meten\",\"br\":\"Muchas ocasiones pero las fallan\",\"bl\":\"Pocas ocasiones y las fallan\",\"tl\":\"Pocas ocasiones pero las meten\"}},\"requiere\":[\"npxg90\",\"npg90\"],\"subtitulo\":\"Jugadores con \u2265{min} min \u00b7 {temporada}\",\"filtros\":{\"posicion\":true,\"nivel\":true,\"sub21\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xG por 90'\",\"ayuda\":\"Ordenados por xG sin penales por 90'\"},{\"id\":\"y\",\"etiqueta\":\"Goles por 90'\",\"ayuda\":\"Ordenados por Goles sin penales por 90'\"}],\"queMirar\":\"Compara los goles que marca cada jugador con los que val\u00edan sus ocasiones. En el eje horizontal est\u00e1 el xG, que suma la probabilidad de gol de cada tiro seg\u00fan desde d\u00f3nde y c\u00f3mo se hizo; en el vertical, los goles reales, ambos por 90 minutos y sin penales. La diagonal marca el punto en que marc\u00f3 justo lo esperado: quien est\u00e1 arriba rinde por encima de sus ocasiones y quien est\u00e1 abajo, por debajo. La l\u00ednea vertical separa al 30% con m\u00e1s xG.\",\"insight\":\"xg_goles_90\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\",\"rendimiento\"],\"minimoPor90\":true,\"posicionesIni\":[\"Defensa\",\"Medio\",\"Delantero\"]};</script>");